mapper.select:
SELECT * FROM COURSE WHERE USE_YN = 'Y'
AND TRAINING_JOB_CATEGORY_ID = #{trainingJobCategoryId}
AND EDUCATION_CATEGORY_ID = #{educationCategoryId}
ORDER BY COURSE_ID DESC

mapper.update:
UPDATE COURSE
TRAINING_JOB_CATEGORY_ID = #{trainingJobCategoryId}, EDUCATION_CATEGORY_ID = #{educationCategoryId}, COURSE_NAME = #{courseName}, COURSE_TYPE = #{courseType}, COURSE_DIVISION = #{courseDivision}, COURSE_COLOR = #{courseColor}, DESCRIPTION = #{description}, TOTAL_HOURS = #{totalHours}, INTRODUCTION = #{introduction}, QUALIFICATION = #{qualification}, TUITION_REFUND_INFO = #{tuitionRefundInfo}, CURRICULUM_CONTENT = #{curriculumContent}, CAREER_PATH = #{careerPath}, RELATED_CERTIFICATION = #{relatedCertification}, USE_YN = #{useYn}, UPDATED_BY = #{updatedBy}, UPDATED_AT = NOW()
WHERE COURSE_ID = #{courseId}

UPDATE COURSE_BATCH
BATCH_NO = #{batchNo}, BATCH_NAME = #{batchName}, CAMPUS_ID = #{campusId}, TRAINING_CODE = #{trainingCode}, STATUS = #{status}, RECRUIT_TYPE = #{recruitType}, START_DATE = #{startDate}, END_DATE = #{endDate}, RECRUIT_COUNT = #{recruitCount}, APPROVAL_COUNT = #{approvalCount}, TUITION_AMOUNT = #{tuitionAmount}, TUITION_VISIBLE_YN = #{tuitionVisibleYn}, GOV_SUPPORT_AMOUNT = #{govSupportAmount}, SELF_PAYMENT_DESC = #{selfPaymentDesc}, ALLOWANCE_TYPE = #{allowanceType}, ALLOWANCE_AMOUNT = #{allowanceAmount}, ALLOWANCE_DESC = #{allowanceDesc}, REPRESENTATIVE_FILE_ID = #{representativeFileId}, CLASS_START_TIME = #{classStartTime}, CLASS_END_TIME = #{classEndTime}, DAILY_HOURS = #{dailyHours}, TRAINING_DAYS = #{trainingDays}, TRAINING_PLACE = #{trainingPlace}, HRD_LINK = #{hrdLink}, STUDENT_RECORD_OPEN_YN = #{studentRecordOpenYn}, LEDGER_VISIBLE_YN = #{ledgerVisibleYn}, UPDATED_BY = #{updatedBy}, UPDATED_AT = NOW()
WHERE COURSE_ID = #{courseId} AND BATCH_ID = #{batchId}

mapper.select:
SELECT COUNT(*) FROM
TRAINING_JOB_CATEGORY WHERE TRAINING_JOB_CATEGORY_ID EDUCATION_COURSE_CATEGORY WHERE EDUCATION_CATEGORY_ID CAMPUS WHERE CAMPUS_ID INSTRUCTOR WHERE INSTRUCTOR_ID
= #{id}
